$=jQuery,$(document).ready((function(){$("select.wp-crm-system-searchable").select2({width:"resolve",ajax:{url:WP_CRM_Dropdown.ajax_url,dataType:"json",delay:250,data:function(e){return{q:e.term,crm:$(this).attr("name"),action:"wp_crm_search",nonce:WP_CRM_Dropdown.wpcrm_nonce}},processResults:function(e){var t=[];return e&&$.each(e,(function(e,n){t.push({id:n[0],text:n[1]})})),{results:t}}},minimumInputLength:3})}));